QString DistributedDeploymentWindow::SelectedGroup()const{const int row=fGroups->currentRow();return row>=0 && fGroups->item(row,0)?fGroups->item(row,0)->data(Qt::UserRole).toString():(fDailyGroups?fDailyGroups->currentData().toString():QString());}
void DistributedDeploymentWindow::RemoveGroup(){const auto id=SelectedGroup();if(id.isEmpty())return;try{const auto activePath=fRoot->text()+"/active-instances.json";if(QFile::exists(activePath)){const auto active=Parse(Read(activePath));for(auto it=active.begin();it!=active.end();++it)if(it.value().toObject()["group_id"]==id)Require(DeploymentInstanceReleased(it.value().toObject()),"Normally stop this group, or use Review terminated group after inspecting hardware and data");}QJsonArray groups;for(const auto &value:fProject["groups"].toArray())if(value.toObject()["id"]!=id)groups.append(value);fProject["groups"]=groups;SaveProject();RefreshTables();}catch(const std::exception &error){fLog->appendPlainText(QString::fromUtf8(error.what()));}}
void DistributedDeploymentWindow::Publish(){try{RefreshSourceFiles();SaveProject();QJsonArray hosts;for(const auto &value:fProject["nodes"].toArray())hosts.append(QJsonObject{{"id",value.toObject()["id"]}});const auto bundle=BuildBundle(fProject["project_id"].toString(),hosts,fProject["groups"].toArray(),fFiles);const auto nodes=fProject["nodes"].toArray();const auto root=fRoot->text(),address=fAddress->text(),programs=QCoreApplication::applicationDirPath();const int port=fPort->value();const auto log=Logger();Async([=]{const auto master=EnsureMaster(root,programs,address,port);return QJsonObject{{"master",master},{"preparation",PrepareProject(master,nodes,bundle,log)}};},[this](QJsonObject result){fMaster=result["master"].toObject();fPreparation=result["preparation"].toObject();RefreshTables();fLog->appendPlainText(tr("All required nodes prepared release %1. You can now start the services." ).arg(fPreparation["release_id"].toString().left(12)));});}catch(const std::exception &error){fLog->appendPlainText(QString::fromUtf8(error.what()));}}
void DistributedDeploymentWindow::Activate(){if(fPreparation.isEmpty()){fLog->appendPlainText(tr("Save and sync first, then wait for all required nodes to finish preparing."));return;}const auto master=fMaster,prepared=fPreparation;const auto nodes=fProject["nodes"].toArray();const auto log=Logger();const auto group=SelectedGroup();if(group.isEmpty()){fLog->appendPlainText(tr("Select the ECC group to start first."));return;}Async([=]{return ActivateProject(master,nodes,prepared,log,group);},[this](QJsonObject result){fActivation=result;RefreshTables();fLog->appendPlainText(tr("Service identities verified. Select an ECC group and click Use this ECC in Run Setup, then connect and acquire as usual."));});}
void DistributedDeploymentWindow::Observe(){if(fMaster.isEmpty())return;const auto master=fMaster;const auto nodes=fProject["nodes"].toArray();Async([=]{return ObserveDeployment(master,nodes);},[this](QJsonObject result){auto nodes=fProject["nodes"].toArray();for(const auto &value:result["hosts"].toArray()){const auto observed=value.toObject();for(int i=0;i<nodes.size();++i)if(nodes[i].toObject()["id"]==observed["node_id"]){auto node=nodes[i].toObject();node["observation"]=observed["online"].toBool()?tr("Agent online; see log for instance processes"):tr("Offline: %1").arg(observed["message"].toString());if(observed["online"].toBool())node["inventory"]=observed;nodes[i]=node;}for(const auto &instance:observed["instances"].toArray()){const auto item=instance.toObject();fLog->appendPlainText(QString("%1 / %2: %3, PIDs=%4").arg(observed["name"].toString(),item["instance_id"].toString(),item["actual_state"].toString(item["phase"].toString()),QString::fromUtf8(QJsonDocument(item["actual_pids"].toArray()).toJson(QJsonDocument::Compact))));}}fProject["nodes"]=nodes;for(const auto &value:result["operations"].toArray()){const auto record=value.toObject();fLog->appendPlainText(tr("Original operation %1: %2 %3").arg(record["request"].toObject()["operation_id"].toString(),record["phase"].toString(),record["observation_error"].toString()));}SaveProject();RefreshTables();});}
void DistributedDeploymentWindow::StopSelected(bool repair){const auto group=SelectedGroup();if(group.isEmpty() || fPreparation.isEmpty()){fLog->appendPlainText(tr("Select a deployed ECC group first."));return;}if(repair && QMessageBox::warning(this,tr("Terminate group"),tr("Terminate only matching backend processes in the selected group? This does not prove boards have stopped, complete a Run or clear UNKNOWN."),QMessageBox::Yes|QMessageBox::No,QMessageBox::No)!=QMessageBox::Yes)return;const auto master=fMaster,prepared=fPreparation;const auto nodes=fProject["nodes"].toArray();const auto log=Logger();Async([=]{return StopGroup(master,nodes,prepared,group,repair,log);},[this](QJsonObject result){fLog->appendPlainText(tr("Selected group result: %1").arg(result["phase"].toString()));});}
void DistributedDeploymentWindow::ReviewTerminatedGroup(){
    const auto group=SelectedGroup();if(fBusy || group.isEmpty() || fMaster.isEmpty())return;
    if(QMessageBox::warning(this,tr("Review terminated group"),tr("Continue only after you have verified that board acquisition is stopped (or the boards have been reset) and existing raw data has been preserved.\n\nThe node will verify that matching backend and receiver processes are absent. This releases only the deployment lock so this group can be edited or removed. It does not mark the old Run complete, clear hardware UNKNOWN, delete data, or start hardware.\n\nHave you verified these conditions?"),QMessageBox::Yes|QMessageBox::Cancel,QMessageBox::Cancel)!=QMessageBox::Yes)return;
    const auto master=fMaster;const auto nodes=fProject["nodes"].toArray();const auto log=Logger();
    Async([=]{return ReleaseTerminatedGroup(master,nodes,group,log);},[this](QJsonObject){RefreshTables();fLog->appendPlainText(tr("Inspection release recorded. You can remove this draft group, or save edits and click Start project services. Old audit and raw data are retained."));});
}
void DistributedDeploymentWindow::UseSelected(){if(fBusy)return;try{fSelected=ConsoleConfiguration(fMaster,fPreparation,fActivation,SelectedGroup(),fBase);accept();}catch(const std::exception &error){fLog->appendPlainText(QString::fromUtf8(error.what()));}}

void DistributedDeploymentWindow::StartAndUse(){
    try{RefreshSourceFiles();SaveProject();const auto selected=SelectedGroup();Require(!selected.isEmpty(),"For first-time setup, add an execution host and an ECC / board group.");QJsonArray hosts;for(const auto &value:fProject["nodes"].toArray())hosts.append(QJsonObject{{"id",value.toObject()["id"]}});const auto bundle=BuildBundle(fProject["project_id"].toString(),hosts,fProject["groups"].toArray(),fFiles);const auto nodes=fProject["nodes"].toArray();const auto root=fRoot->text(),address=fAddress->text(),programs=QCoreApplication::applicationDirPath();const int port=fPort->value();const auto log=Logger();Async([=]{log("Starting / checking master configuration service…");const auto master=EnsureMaster(root,programs,address,port);const auto prepared=PrepareProject(master,nodes,bundle,log);const auto active=ActivateProject(master,nodes,prepared,log);return QJsonObject{{"master",master},{"preparation",prepared},{"activation",active}};},[this,selected](QJsonObject result){fMaster=result["master"].toObject();fPreparation=result["preparation"].toObject();fActivation=result["activation"].toObject();if(fCloseAfterWait || (fCanceled && fCanceled->load())){RefreshTables();return;}fSelected=ConsoleConfiguration(fMaster,fPreparation,fActivation,selected,fBase);accept();});}catch(const std::exception &error){fLog->appendPlainText(QString::fromUtf8(error.what()));}
}

void DistributedDeploymentWindow::UpdatePathSummary(){
    if(!fPathSummary)return;
    QJsonObject group;const auto selected=fDailyGroups->currentData().toString();
    for(const auto &value:fProject["groups"].toArray())if(value.toObject()["id"]==selected)group=value.toObject();
    if(group.isEmpty()){fPathSummary->setText(tr("Select an ECC group to see its configuration and data folders."));return;}
    QStringList lines{tr("Source XML/XCFG (master): %1").arg(group["master_repository"].toString())};
    bool eccSeen=false,dataSeen=false;
    for(const auto &hostValue:fProject["nodes"].toArray()){
        const auto host=hostValue.toObject();
        for(const auto &value:host["inventory"].toObject()["instances"].toArray()){
            const auto instance=value.toObject();if(instance["group_id"]!=selected)continue;
            if(instance["role"]=="ecc" && !instance["configuration_repository"].toString().isEmpty()){
                lines<<tr("ECC cache on %1 (last prepared): %2").arg(host["name"].toString(),instance["configuration_repository"].toString());eccSeen=true;
            }else if(instance["role"]=="receiver" && !instance["data_directory"].toString().isEmpty()){
                const auto raw=instance["data_directory"].toString();
                lines<<tr("Raw .graw on %1 (last prepared working folder): %2").arg(host["name"].toString(),raw);
                lines<<tr("After successful Sentry archive: %1/%2/run_NNNN").arg(raw,group["experiment"].toString());dataSeen=true;
            }
        }
    }
    if(!eccSeen)lines<<tr("ECC cache: shown after preparing services and refreshing hosts; files are copied automatically.");
    if(!dataSeen)for(const auto &rxValue:group["receivers"].toArray()){
        const auto rx=rxValue.toObject();for(const auto &hostValue:fProject["nodes"].toArray()){
            const auto host=hostValue.toObject();if(host["id"]!=rx["node_id"])continue;
            const auto root=host["inventory"].toObject()["data_directory"].toString();
            if(!root.isEmpty())lines<<tr("Planned project folder on %1: %2").arg(host["name"].toString(),group["project_mode"].toBool()?group["project_directories"].toObject()[host["id"].toString()].toString(root):QDir(root).filePath(selected+'-'+rx["id"].toString()));
        }
    }
    QString records=fBase.outputDir;
    if(!fMaster.isEmpty() && !fActivation["release_id"].toString().isEmpty()){
        const auto path=fMaster["root"].toString()+"/console/"+fActivation["release_id"].toString()+'/'+selected+"/envoy.yml";
        RunConfig saved;QString error;if(QFileInfo::exists(path) && saved.Load(path,&error))records=saved.outputDir;
    }
    lines<<tr("GUI records root (YAML / journal / CSV / backups, not raw data): %1").arg(records);
    fPathSummary->setText(lines.join('\n'));
}

void DistributedDeploymentWindow::RefreshSourceFiles(){
 auto groups=fProject["groups"].toArray();auto files=fFiles;QSet<QString> used;
 for(int i=0;i<groups.size();++i){auto group=groups[i].toObject();if(group["project_mode"].toBool()){
  group["master_repository"]=QFileInfo(fSource->text().trimmed()).absoluteFilePath();group["sync_configuration"]=fSync->isChecked();group["repository_files"]=OriginalRepository(group["master_repository"].toString(),group["id"].toString(),&files);groups[i]=group;
 }for(const auto &value:group["repository_files"].toArray())used.insert(value.toObject()["file"].toString());}
 for(auto it=files.begin();it!=files.end();)if(!used.contains(it.key()))it=files.erase(it);else ++it;
 fFiles=files;fProject["groups"]=groups;
}
void DistributedDeploymentWindow::OpenSyncDialog(){
 if(fBusy)return;
 try{
  RefreshSourceFiles();SaveProject();const auto nodes=fProject["nodes"].toArray();Require(!nodes.isEmpty(),"Add this computer or pair a slave first");
  QDialog dialog(this);dialog.setWindowTitle(tr("Sync project configuration"));QVBoxLayout layout(&dialog);
  auto *source=new QLabel(tr("Source on master: %1\nSelect execution hosts. Slaves receive and automatically apply files to their own project folders; running projects cache the update without replacing active files.").arg(fSource->text()),&dialog);source->setWordWrap(true);layout.addWidget(source);
  QList<QCheckBox *> choices;for(const auto &value:nodes){const auto node=value.toObject();auto *check=new QCheckBox(node["name"].toString()+" — "+node["url"].toString(),&dialog);check->setProperty("node_id",node["id"].toString());check->setChecked(true);choices.append(check);layout.addWidget(check);}
  QDialogButtonBox buttons(QDialogButtonBox::Ok|QDialogButtonBox::Cancel,&dialog);buttons.button(QDialogButtonBox::Ok)->setText(tr("Sync selected hosts"));layout.addWidget(&buttons);connect(&buttons,&QDialogButtonBox::accepted,&dialog,&QDialog::accept);connect(&buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);if(dialog.exec()!=QDialog::Accepted)return;
  QSet<QString> targets;for(auto *choice:choices)if(choice->isChecked())targets.insert(choice->property("node_id").toString());Require(!targets.isEmpty(),"Select at least one execution host");
  QJsonArray hosts;for(const auto &value:nodes)hosts.append(QJsonObject{{"id",value.toObject()["id"]}});const auto bundle=BuildBundle(fProject["project_id"].toString(),hosts,fProject["groups"].toArray(),fFiles);const auto root=fRoot->text(),address=fAddress->text(),programs=QCoreApplication::applicationDirPath();const int port=fPort->value();const auto log=Logger();
  Async([=]{const auto master=EnsureMaster(root,programs,address,port);return QJsonObject{{"master",master},{"sync",SyncProject(master,nodes,bundle,targets,log)}};},[this](QJsonObject result){fMaster=result["master"].toObject();fLog->appendPlainText(tr("Configuration delivery finished. Applied / pending results are shown above; no acquisition command was sent."));});
 }catch(const std::exception &error){fLog->appendPlainText(QString::fromUtf8(error.what()));}
}

void DistributedDeploymentWindow::StopProjectServices(){
 if(fBusy || fMaster.isEmpty())return;const auto master=fMaster,prepared=fPreparation,project=fProject;const auto nodes=project["nodes"].toArray();const auto log=Logger();
 Async([=]{const auto active=Parse(Read(master["root"].toString()+"/active-instances.json"));
  for(auto it=active.begin();it!=active.end();++it){const auto entry=it.value().toObject();if(entry["role"]!="ecc" || entry["phase"]!="active")continue;for(const auto &v:project["groups"].toArray())if(v.toObject()["id"]==entry["group_id"]){const auto ecc=v.toObject()["ecc"].toObject();const int state=OriginalEccState(ecc["address"].toString(),ecc["port"].toInt());Require(state!=5 && state!=6,"Stop the Run in the main window before stopping project services");}}
  QJsonArray receipts;for(const auto &v:project["groups"].toArray()){const auto group=v.toObject();if(active.contains(group["id"].toString()+"-ecc"))receipts.append(StopGroup(master,nodes,prepared,group["id"].toString(),false,log));}return QJsonObject{{"receipts",receipts}};
 },[this](QJsonObject){fLog->appendPlainText(tr("Project services stopped. Configuration, raw files and logs were retained."));});
}
